  "ststr.w.v.stable": "<b>Stable: the core is non-empty.</b> Paying every coalition what its own platform would earn needs at least {need}, and the platform earns <i>v</i>(<i>N</i>) = {vN}.",
  "ststr.w.v.margin": "The LP core point {x} gives every coalition at least {e} more than its own platform would earn.",
  "ststr.w.v.thin": "The LP core point is {x}; every core allocation leaves at least one coalition with exactly its own revenue.",
